    title: 'Carbon (C)',
    tooltip: 'C · centre of the tetrahedron',
    body: 'Carbon sits at the centre. Its four equivalent sp³ hybrid orbitals point at the corners of a tetrahedron, so every C–H bond is identical: 109 pm long, 109.5° apart.'
  });
});
for (let i = 0; i < 4; i++) {
  [[spaceH[i], gSpace], [ballH[i], gBall]].forEach(([m, g]) => {
    guardVisible(m, g);
