    });
  });
}

/* ── UI wiring ───────────────────────────────────────────────────────────── */
const btnSpace = document.getElementById('repSpace');
const btnStruct = document.getElementById('repStruct');
const btnBall = document.getElementById('repBall');
const slider = document.getElementById('bondAngle');
let repName = 'Structural drawing';

function setRep(name, moveCamera) {
  repName = name;
  fades[0].tgt = name === 'Space-filling' ? 1 : 0;
  fades[1].tgt = name === 'Structural drawing' ? 1 : 0;
  fades[2].tgt = name === 'Ball-and-stick' ? 1 : 0;
  btnSpace.classList.toggle('active', name === 'Space-filling');
  btnStruct.classList.toggle('active', name === 'Structural drawing');
  btnBall.classList.toggle('active', name === 'Ball-and-stick');
  if (moveCamera !== false) animateCameraTo(name === 'Structural drawing' ? VIEW_FLAT : VIEW_3D);
}
btnSpace.addEventListener('click', () => setRep('Space-filling'));
btnStruct.addEventListener('click', () => setRep('Structural drawing'));
btnBall.addEventListener('click', () => setRep('Ball-and-stick'));

let angleTween = null;
slider.addEventListener('input', () => { angleTween = null; applyAngle(parseFloat(slider.value)); });
document.getElementById('btnIdeal').addEventListener('click', () => { angleTween = { from: parseFloat(slider.value), to: 109.5, t: 0 }; });

/* ── guided tour ─────────────────────────────────────────────────────────── */
const STEPS = [
  { title: '1 · Solid volume', narr: 'The space-filling model shows methane as four bulky hydrogen spheres crowding a nearly hidden carbon — accurate for size, useless for reading angles.', rep: 'Space-filling', angle: 109.5 },
  { title: '2 · Measured drawing', narr: 'The structural drawing strips the volume away and adds numbers: the magenta arc marks the 109.5º H–C–H bond angle, the vertical arrow the 109 pm C–H bond length. The bold wedge shows the fourth hydrogen coming toward you.', rep: 'Structural drawing', angle: 109.5 },
  { title: '3 · Distort the angle', narr: 'Push one hydrogen away from 109.5º and watch the readout: the four bonds stop being equivalent and the neighbouring angles compress, so the molecule no longer looks tetrahedral.', rep: 'Structural drawing', angle: 140 },
  { title: '4 · Back to the tetrahedron', narr: 'Restoring 109.5º in the ball-and-stick model reveals the open skeleton: four identical bonds spread as far apart as possible. Orbit to see it from any side.', rep: 'Ball-and-stick', angle: 109.5 }
];
let stepIdx = 1;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setRep(s.rep);
  angleTween = { from: parseFloat(slider.value), to: s.angle, t: 0 };
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarr').textContent = s.narr;
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
let playTimer = null;
const btnPlay = document.getElementById('stepPlay');
btnPlay.addEventListener('click', () => {
  if (playTimer) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); return; }
  btnPlay.textContent = '❚❚ Pause'; btnPlay.classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => {
    if (stepIdx === STEPS.length - 1) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); return; }
    goToStep(stepIdx + 1);
  }, 5200);
});
goToStep(1);

/* ── per-frame tweening ──────────────────────────────────────────────────── */
function tick() {
  requestAnimationFrame(tick);
  applyFades();
  if (angleTween) {
    angleTween.t = Math.min(1, angleTween.t + 0.035);
    const e = angleTween.t < 0.5 ? 2 * angleTween.t * angleTween.t : 1 - Math.pow(-2 * angleTween.t + 2, 2) / 2;
    const v = angleTween.from + (angleTween.to - angleTween.from) * e;
    slider.value = v.toFixed(1);
    applyAngle(parseFloat(slider.value));
    if (angleTween.t >= 1) angleTween = null;
  }
  if (camTween) {
    camTween.t = Math.min(1, camTween.t + 0.04);
    const e = camTween.t < 0.5 ? 2 * camTween.t * camTween.t : 1 - Math.pow(-2 * camTween.t + 2, 2) / 2;
    camera.position.lerpVectors(camTween.sp, camTween.ep, e);
    controls.target.lerpVectors(camTween.st, camTween.et, e);
    controls.update();
    if (camTween.t >= 1) camTween = null;
  }
}
tick();
// @FIGURE_CODE_END

