  goToStep(stepIdx + 1);
  playTimer = setInterval(() => {
    if (stepIdx === STEPS.length - 1) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); return; }
    goToStep(stepIdx + 1);
  }, 5200);
});
goToStep(1);

/* ── per-frame tweening ──────────────────────────────────────────────────── */
function tick() {
  requestAnimationFrame(tick);
  applyFades();
  if (angleTween) {
    angleTween.t = Math.min(1, angleTween.t + 0.035);
    const e = angleTween.t < 0.5 ? 2 * angleTween.t * angleTween.t : 1 - Math.pow(-2 * angleTween.t + 2, 2) / 2;
    const v = angleTween.from + (angleTween.to - angleTween.from) * e;
    slider.value = v.toFixed(1);
    applyAngle(parseFloat(slider.value));
    if (angleTween.t >= 1) angleTween = null;
  }
  if (camTween) {
    camTween.t = Math.min(1, camTween.t + 0.04);
    const e = camTween.t < 0.5 ? 2 * camTween.t * camTween.t : 1 - Math.pow(-2 * camTween.t + 2, 2) / 2;
    camera.position.lerpVectors(camTween.sp, camTween.ep, e);
    controls.target.lerpVectors(camTween.st, camTween.et, e);
    controls.update();
    if (camTween.t >= 1) camTween = null;
  }
}
