// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC (left→right composite, as in the source figure) ───────────
   LEFT PANEL — space-filling model (group gSpace @ x=-4.6)
     C          → SphereGeometry(0.70)  MeshPhong #4A4A4A
     H x4       → SphereGeometry(0.62)  MeshPhong #E6E3DA (interpenetrating)
   MIDDLE PANEL — structural drawing (group gStruct @ x=0, flat z=0)
     3 plain bonds (up 90°, left 201°, right -27°) → thin PlaneGeometry quads, black
     wedge bond (down-right, -63°)                 → ShapeGeometry trapezoid, black
     2 magenta dashed rays (extend up + left bond) → Line + LineDashedMaterial #E0218A
     bond-angle arc + 2 heads                      → TubeGeometry + ConeGeometry, #E0218A
     2 dashed length leaders + vertical double arrow → Line/quad + ConeGeometry, #E0218A
     glyphs C, H×4                                 → addLabel (black, 17px)
     'Bond angle 109.5º', 'Bond length 109 pm'     → addLabel (black, 15px)
     invisible hit spheres                         → SphereGeometry(0.22) material.visible=false
   RIGHT PANEL — ball-and-stick model (group gBall @ x=4.8)
     C          → SphereGeometry(0.35)  MeshPhong #3F4448
     H x4       → SphereGeometry(0.25)  MeshPhong #DCDAD3
     bonds x4   → CylinderGeometry(0.07,0.07,1) MeshPhong #AFC3D4
──────────────────────────────────────────────────────────────────────────── */

const DEG = Math.PI / 180;
const MAGENTA = 0xE0218A;

/* ── lighting ────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.58));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.85); keyLight.position.set(3, 5, 5); scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.32); fillLight.position.set(-4, 1.5, 3); scene.add(fillLight);
const rimLight = new THREE.DirectionalLight(0xffffff, 0.22); rimLight.position.set(0, -4, 2); scene.add(rimLight);

/* ── shared tetrahedral geometry ─────────────────────────────────────────── */
const BOND_LEN = 1.09;
const dirsBase = [
  new THREE.Vector3(1, 1, 1).normalize(),
  new THREE.Vector3(1, -1, -1).normalize(),
  new THREE.Vector3(-1, 1, -1).normalize(),
  new THREE.Vector3(-1, -1, 1).normalize()
];
const I_UP = 0, I_REF = 2;
const IDEAL = 109.4712206;

function currentDirs(angleDeg) {
  const out = dirsBase.map(v => v.clone());
  const axis = new THREE.Vector3().crossVectors(dirsBase[I_REF], dirsBase[I_UP]).normalize();
  out[I_UP] = dirsBase[I_UP].clone().applyAxisAngle(axis, (angleDeg - IDEAL) * DEG);
  return out;
}

/* ── panel groups ────────────────────────────────────────────────────────── */
const X_SPACE = -4.6, X_BALL = 4.8;
const gSpace = new THREE.Group(); gSpace.position.x = X_SPACE;
const gBall = new THREE.Group(); gBall.position.x = X_BALL;
const gStruct = new THREE.Group();
gSpace.rotation.set(-0.22, Math.PI / 4, 0);
gBall.rotation.set(0.30, Math.PI / 4 + 0.30, 0);
scene.add(gSpace, gBall, gStruct);

/* ── space-filling model ─────────────────────────────────────────────────── */
const matSpaceC = new THREE.MeshPhongMaterial({ color: 0x4A4A4A, shininess: 55, specular: 0x8e8e8e });
const matSpaceH = new THREE.MeshPhongMaterial({ color: 0xE6E3DA, shininess: 78, specular: 0xffffff });
const spaceC = new THREE.Mesh(new THREE.SphereGeometry(0.70, 48, 32), matSpaceC);
gSpace.add(spaceC);
const spaceH = [];
for (let i = 0; i < 4; i++) {
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.62, 48, 32), matSpaceH);
  gSpace.add(s); spaceH.push(s);
}

/* ── ball-and-stick model ────────────────────────────────────────────────── */
const matBallC = new THREE.MeshPhongMaterial({ color: 0x3F4448, shininess: 60, specular: 0x9a9a9a });
const matBallH = new THREE.MeshPhongMaterial({ color: 0xDCDAD3, shininess: 80, specular: 0xffffff });
const matBallHhi = new THREE.MeshPhongMaterial({ color: 0xDCDAD3, shininess: 80, specular: 0xffffff, emissive: 0x3a0c26 });
const matRod = new THREE.MeshPhongMaterial({ color: 0xAFC3D4, shininess: 45, specular: 0xdddddd });
const ballC = new THREE.Mesh(new THREE.SphereGeometry(0.35, 40, 28), matBallC);
gBall.add(ballC);
const ballH = [], rods = [];
for (let i = 0; i < 4; i++) {
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.25, 36, 24), i === I_UP ? matBallHhi : matBallH);
  gBall.add(s); ballH.push(s);
  const r = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 1, 18), matRod);
  gBall.add(r); rods.push(r);
}
const UPY = new THREE.Vector3(0, 1, 0);
function setRod(mesh, dir) {
  const start = dir.clone().multiplyScalar(0.28);
  const end = dir.clone().multiplyScalar(BOND_LEN);
  mesh.position.copy(start).add(end).multiplyScalar(0.5);
  mesh.scale.set(1, end.distanceTo(start), 1);
  mesh.quaternion.setFromUnitVectors(UPY, dir);
}

/* ── structural (flat) panel ─────────────────────────────────────────────── */
const matBlack = new THREE.MeshBasicMaterial({ color: 0x111111, side: THREE.DoubleSide });
const matMag = new THREE.MeshBasicMaterial({ color: MAGENTA, side: THREE.DoubleSide });
const matDash = new THREE.LineDashedMaterial({ color: MAGENTA, dashSize: 0.072, gapSize: 0.052 });
const structDyn = new THREE.Group();
const structHits = new THREE.Group();
gStruct.add(structDyn, structHits);

function quad2d(ax, ay, bx, by, w, mat) {
  const dx = bx - ax, dy = by - ay, len = Math.hypot(dx, dy) || 1e-4;
  const m = new THREE.Mesh(new THREE.PlaneGeometry(len, w), mat);
  m.position.set((ax + bx) / 2, (ay + by) / 2, 0);
  m.rotation.z = Math.atan2(dy, dx);
  return m;
}
function poly2d(pts, mat) {
  const s = new THREE.Shape();
  s.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) s.lineTo(pts[i].x, pts[i].y);
  s.closePath();
  return new THREE.Mesh(new THREE.ShapeGeometry(s), mat);
}
function dashed2d(a, b) {
  const g = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(a.x, a.y, 0), new THREE.Vector3(b.x, b.y, 0)]);
  const l = new THREE.Line(g, matDash);
  l.computeLineDistances();
  return l;
}
function head2d(x, y, ang, size) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(size * 0.46, size, 16), matMag);
  m.position.set(x, y, 0);
  m.rotation.z = ang - Math.PI / 2;
  return m;
}
function arcTube(r, a0, a1, tubeR) {
  const pts = [];
  for (let i = 0; i <= 48; i++) {
    const a = a0 + (a1 - a0) * i / 48;
    pts.push(new THREE.Vector3(Math.cos(a) * r, Math.sin(a) * r, 0));
  }
  return new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 72, tubeR, 8, false), matMag);
}
function clearGroup(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const c = g.children[i]; g.remove(c); c.geometry && c.geometry.dispose();
  }
}

/* labels */
const lblC = addLabel('C', new THREE.Vector3(), { fontSize: '17px' });
const lblH = [];
for (let i = 0; i < 4; i++) lblH.push(addLabel('H', new THREE.Vector3(), { fontSize: '17px' }));
const lblAngle = addLabel('Bond angle<br>109.5º', new THREE.Vector3(-1.80, 1.18, 0), { fontSize: '15px' });
const lblLength = addLabel('Bond<br>length<br>109 pm', new THREE.Vector3(2.05, 0.42, 0), { fontSize: '15px' });
const structLabels = [lblC, ...lblH, lblAngle, lblLength];

/* invisible hover targets inside the structural drawing */
const hitMat = new THREE.MeshBasicMaterial({ visible: false });
const hits = [];
for (let i = 0; i < 7; i++) {
  const h = new THREE.Mesh(new THREE.SphereGeometry(0.22, 10, 8), hitMat);
  structHits.add(h); hits.push(h);
}

const LEFT_DEG = 201, RIGHT_DEG = -27, WEDGE_DEG = -63;
const LEN_UP = 0.90, LEN_LEFT = 0.90, LEN_RIGHT = 0.72, LEN_WEDGE = 0.86;

function buildStructural(angleDeg) {
  clearGroup(structDyn);
  const upDeg = LEFT_DEG - angleDeg;
  const upRad = upDeg * DEG;
  const pUp = new THREE.Vector2(Math.cos(upRad), Math.sin(upRad)).multiplyScalar(LEN_UP);
  const pLeft = new THREE.Vector2(Math.cos(LEFT_DEG * DEG), Math.sin(LEFT_DEG * DEG)).multiplyScalar(LEN_LEFT);
  const pRight = new THREE.Vector2(Math.cos(RIGHT_DEG * DEG), Math.sin(RIGHT_DEG * DEG)).multiplyScalar(LEN_RIGHT);
  const pW = new THREE.Vector2(Math.cos(WEDGE_DEG * DEG), Math.sin(WEDGE_DEG * DEG)).multiplyScalar(LEN_WEDGE);

  const gapC = 0.185, gapH = 0.175, lw = 0.028;
  for (const p of [pUp, pLeft, pRight]) {
    const dv = p.clone().normalize();
    const a = dv.clone().multiplyScalar(gapC);
    const b = p.clone().sub(dv.clone().multiplyScalar(gapH));
    structDyn.add(quad2d(a.x, a.y, b.x, b.y, lw, matBlack));
  }
  /* solid wedge, narrow at C and wide at H — points down-and-right */
  {
    const dv = pW.clone().normalize();
    const a = dv.clone().multiplyScalar(gapC);
    const b = pW.clone().sub(dv.clone().multiplyScalar(gapH));
    const n = new THREE.Vector2(-dv.y, dv.x);
    structDyn.add(poly2d([
      a.clone().add(n.clone().multiplyScalar(0.016)),
      b.clone().add(n.clone().multiplyScalar(0.085)),
      b.clone().sub(n.clone().multiplyScalar(0.085)),
      a.clone().sub(n.clone().multiplyScalar(0.016))
    ], matBlack));
  }
  /* magenta dashed rays extending the top bond and the left bond */
  const upDir = new THREE.Vector2(Math.cos(upRad), Math.sin(upRad));
  structDyn.add(dashed2d(upDir.clone().multiplyScalar(LEN_UP + 0.22), upDir.clone().multiplyScalar(LEN_UP + 0.80)));
  const lr = new THREE.Vector2(Math.cos(LEFT_DEG * DEG), Math.sin(LEFT_DEG * DEG));
  structDyn.add(dashed2d(lr.clone().multiplyScalar(LEN_LEFT + 0.20), lr.clone().multiplyScalar(LEN_LEFT + 0.78)));

  /* double-headed curved arrow spanning the bond angle */
  const aR = 1.26, a0 = (upDeg + 7) * DEG, a1 = (LEFT_DEG - 7) * DEG;
  structDyn.add(arcTube(aR, a0, a1, 0.019));
  structDyn.add(head2d(Math.cos(a0) * aR, Math.sin(a0) * aR, Math.atan2(-Math.cos(a0), Math.sin(a0)), 0.17));
  structDyn.add(head2d(Math.cos(a1) * aR, Math.sin(a1) * aR, Math.atan2(Math.cos(a1), -Math.sin(a1)), 0.17));

  /* bond-length leaders + vertical double arrow */
  const xEnd = 1.66, xArrow = 1.46;
  structDyn.add(dashed2d(new THREE.Vector2(pUp.x + 0.20, pUp.y), new THREE.Vector2(xEnd, pUp.y)));
  structDyn.add(dashed2d(new THREE.Vector2(0.32, 0), new THREE.Vector2(xEnd, 0)));
  structDyn.add(quad2d(xArrow, 0.03, xArrow, pUp.y - 0.03, 0.022, matMag));
  structDyn.add(head2d(xArrow, pUp.y, Math.PI / 2, 0.16));
  structDyn.add(head2d(xArrow, 0, -Math.PI / 2, 0.16));

  /* glyph + hit-target placement */
  lblC.pos.set(0, 0, 0);
  const pts = [pUp, pLeft, pRight, pW];
  for (let i = 0; i < 4; i++) lblH[i].pos.set(pts[i].x, pts[i].y, 0);
  lblLength.pos.set(2.05, pUp.y / 2, 0);
  hits[0].position.set(0, 0, 0);
  for (let i = 0; i < 4; i++) hits[i + 1].position.set(pts[i].x, pts[i].y, 0);
  const am = (a0 + a1) / 2;
  hits[5].position.set(Math.cos(am) * aR, Math.sin(am) * aR, 0);
  hits[6].position.set(xArrow, pUp.y / 2, 0);
}

/* ── apply the bond angle to all three representations ───────────────────── */
function applyAngle(v) {
  const dirs = currentDirs(v);
  for (let i = 0; i < 4; i++) {
    const p = dirs[i].clone().multiplyScalar(BOND_LEN);
    spaceH[i].position.copy(p);
    ballH[i].position.copy(p);
    setRod(rods[i], dirs[i]);
  }
  buildStructural(v);
  const ideal = Math.abs(v - 109.5) < 0.26;
  const col = ideal ? '#111' : '#E0218A';
  lblAngle.div.innerHTML = 'Bond angle<br><span style="color:' + col + '">' + v.toFixed(1) + 'º</span>';
  document.getElementById('angleReadout').innerHTML =
    'measured H–C–H = <b>' + v.toFixed(1) + '°</b>' +
    (ideal ? ' <span style="color:#0f8a35">✓ tetrahedral</span>'
           : ' <span style="color:#c0176f">distorted</span>');
}

/* ── cross-fading between representations ────────────────────────────────── */
const fades = [
  { g: gSpace, mats: [matSpaceC, matSpaceH], labels: [], cur: 1, tgt: 1 },
  { g: gStruct, mats: [matBlack, matMag, matDash], labels: structLabels, cur: 1, tgt: 1 },
  { g: gBall, mats: [matBallC, matBallH, matBallHhi, matRod], labels: [], cur: 1, tgt: 1 }
];
function applyFades() {
  for (const f of fades) {
    if (Math.abs(f.cur - f.tgt) > 0.004) f.cur += (f.tgt - f.cur) * 0.14;
    else f.cur = f.tgt;
    f.g.visible = f.cur > 0.012;
    for (const m of f.mats) { m.transparent = f.cur < 0.995; m.opacity = f.cur; }
    for (const l of f.labels) {
      l.div.style.opacity = f.cur;
      l.div.style.visibility = f.cur > 0.02 ? 'visible' : 'hidden';
    }
  }
}

/* ── build geometry first, then camera ───────────────────────────────────── */
applyAngle(109.5);
applyFades();

/* ── camera poses (orthographic: each panel stays undistorted) ───────────── */
const MODES = {
  all:    { cx: -0.10, cy: 0.18, halfW: 6.35, halfH: 1.95, az: 87, el: 5, frac: 0.93 },
  space:  { cx: X_SPACE, cy: 0.00, halfW: 1.90, halfH: 1.90, az: 82, el: 8, frac: 0.82 },
  struct: { cx: 0.15, cy: 0.20, halfW: 2.90, halfH: 1.70, az: 90, el: 0, frac: 0.88 },
  ball:   { cx: X_BALL, cy: 0.00, halfW: 1.55, halfH: 1.55, az: 84, el: 7, frac: 0.82 }
};
function poseFor(key) {
  const p = MODES[key];
  const az = p.az * DEG, el = p.el * DEG;
  const dir = new THREE.Vector3(Math.cos(az) * Math.cos(el), Math.sin(el), Math.sin(az) * Math.cos(el));
  const target = new THREE.Vector3(p.cx, p.cy, 0);
  const pos = target.clone().add(dir.multiplyScalar(16));
  const zoom = Math.min(d * p.frac / p.halfH, d * aspect * p.frac / p.halfW);
  return { pos, target, zoom };
}
function setPose(pose) {
  camera.position.copy(pose.pos);
  controls.target.copy(pose.target);
  if (camera.isOrthographicCamera) camera.zoom = pose.zoom;
  camera.updateProjectionMatrix();
  controls.update();
}
setCameraView({ projection: 'orthographic', azimuthDeg: 87, elevationDeg: 5, heightFraction: 0.9, target: [-0.1, 0.18, 0] });
let mode = 'all';
let poseLocked = true;
let camTween = null;
setPose(poseFor('all'));
canvas.addEventListener('pointerdown', () => { poseLocked = false; camTween = null; });
canvas.addEventListener('wheel', () => { poseLocked = false; camTween = null; }, { passive: true });

/* ── hover / click explanations ──────────────────────────────────────────── */
function guardVisible(mesh, group) {
  mesh.raycast = function (rc, ints) {
    if (!group.visible) return;
    THREE.Mesh.prototype.raycast.call(this, rc, ints);
  };
}
const H_NAMES = ['top (angle-controlled)', 'lower-front', 'left', 'rear'];
[[spaceC, gSpace], [ballC, gBall]].forEach(([m, g]) => {
  guardVisible(m, g);
  registerInteractive(m, {
    title: 'Carbon (C)',
    tooltip: 'C · centre of the tetrahedron',
    body: 'Carbon sits at the centre. Its four equivalent sp³ hybrid orbitals point at the corners of a tetrahedron, so every C–H bond is identical: 109 pm long and 109.5° from each neighbour.'
  });
});
for (let i = 0; i < 4; i++) {
  [[spaceH[i], gSpace], [ballH[i], gBall]].forEach(([m, g]) => {
    guardVisible(m, g);
    registerInteractive(m, {
      title: 'Hydrogen (H) — ' + H_NAMES[i],
      tooltip: 'H · 109 pm from C',
      body: 'Held by one σ bond 109 pm (1.09 Å) from the carbon nucleus — the same length dimensioned by the magenta arrow in the structural drawing. In the undistorted molecule it makes a 109.5° angle with every other hydrogen.'
    });
  });
}
const HIT_INFO = [
  { title: 'Carbon atom (drawing)', tooltip: 'C', body: 'In the flat structural drawing the carbon is just the letter C — but it still stands for the same atom drawn as the dark sphere in the other two models.' },
  { title: 'Top hydrogen', tooltip: 'H in the plane of the page', body: 'Drawn with a plain line, so this bond lies in the plane of the page. The slider swings this hydrogen to change the H–C–H angle.' },
  { title: 'Left hydrogen', tooltip: 'H in the plane of the page', body: 'A plain line: this bond also lies in the plane of the page. The magenta arc measures the angle between this bond and the top one.' },
  { title: 'Right hydrogen', tooltip: 'H in the plane of the page', body: 'A third plain-line bond in the plane of the page.' },
  { title: 'Wedge hydrogen', tooltip: 'H coming out of the page', body: 'The solid wedge — narrow at carbon, wide at hydrogen — means this bond points out of the page, toward you. That is how a flat drawing encodes the third dimension you can see directly in the two 3D models.' },
  { title: 'Bond angle, 109.5°', tooltip: 'bond angle 109.5º', body: 'The tetrahedral angle. Four bonding pairs repel each other equally, so they spread as far apart as possible: 109.5° between every pair.' },
  { title: 'Bond length, 109 pm', tooltip: 'bond length 109 pm', body: 'The C–H internuclear distance in methane, 109 pm (1.09 Å). All four bonds have exactly this length.' }
];
for (let i = 0; i < hits.length; i++) {
  guardVisible(hits[i], gStruct);
  registerInteractive(hits[i], HIT_INFO[i]);
}

/* ── UI wiring ───────────────────────────────────────────────────────────── */
const btnAll = document.getElementById('repAll');
const btnSpace = document.getElementById('repSpace');
const btnStruct = document.getElementById('repStruct');
const btnBall = document.getElementById('repBall');
const slider = document.getElementById('bondAngle');

function startCamTween(key) {
  camTween = {
    t: 0, key,
    sp: camera.position.clone(),
    st: controls.target.clone(),
    sz: camera.zoom
  };
  poseLocked = true;
}
function setRep(key, moveCamera) {
  mode = key;
  fades[0].tgt = (key === 'all' || key === 'space') ? 1 : 0;
  fades[1].tgt = (key === 'all' || key === 'struct') ? 1 : 0;
  fades[2].tgt = (key === 'all' || key === 'ball') ? 1 : 0;
  btnAll.classList.toggle('active', key === 'all');
  btnSpace.classList.toggle('active', key === 'space');
  btnStruct.classList.toggle('active', key === 'struct');
  btnBall.classList.toggle('active', key === 'ball');
  if (moveCamera !== false) startCamTween(key);
}
