                    orientation qBall: H upper-left, H right, H lower-left, H lower-front
──────────────────────────────────────────────────────────────────────────── */

const DEG = Math.PI / 180;
const MAGENTA = 0xE0218A;

/* ── lighting ────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.60));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.80); keyLight.position.set(2.5, 5, 5); scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.34); fillLight.position.set(-4, 1.5, 3); scene.add(fillLight);
const rimLight = new THREE.DirectionalLight(0xffffff, 0.20); rimLight.position.set(0, -4, 2); scene.add(rimLight);

/* ── shared tetrahedral geometry (one bond "up", three in a tripod) ──────── */
const BOND_LEN = 1.09;
const S = Math.sqrt(8) / 3;          // sin(109.47°)
const dirsBase = [
  new THREE.Vector3(0, 1, 0),
  new THREE.Vector3(S, -1 / 3, 0),
  new THREE.Vector3(S * Math.cos(120 * DEG), -1 / 3, S * Math.sin(120 * DEG)),
  new THREE.Vector3(S * Math.cos(240 * DEG), -1 / 3, S * Math.sin(240 * DEG))
].map(v => v.normalize());
const I_UP = 0, I_REF = 2;
const IDEAL = 109.4712206;

function currentDirs(angleDeg) {
  const out = dirsBase.map(v => v.clone());
  const axis = new THREE.Vector3().crossVectors(dirsBase[I_REF], dirsBase[I_UP]).normalize();
  out[I_UP] = dirsBase[I_UP].clone().applyAxisAngle(axis, (angleDeg - IDEAL) * DEG);
  return out;
}

