/* ── UI wiring ───────────────────────────────────────────────────────────── */
const btnAll = document.getElementById('repAll');
const btnSpace = document.getElementById('repSpace');
const btnStruct = document.getElementById('repStruct');
const btnBall = document.getElementById('repBall');
const slider = document.getElementById('bondAngle');

function startCamTween(key) {
  camTween = {
    t: 0, key,
    sp: camera.position.clone(),
    st: controls.target.clone(),
    sz: camera.zoom
  };
  poseLocked = true;
}
function setRep(key, moveCamera) {
  mode = key;
  fades[0].tgt = (key === 'all' || key === 'space') ? 1 : 0;
  fades[1].tgt = (key === 'all' || key === 'struct') ? 1 : 0;
  fades[2].tgt = (key === 'all' || key === 'ball') ? 1 : 0;
  btnAll.classList.toggle('active', key === 'all');
  btnSpace.classList.toggle('active', key === 'space');
  btnStruct.classList.toggle('active', key === 'struct');
  btnBall.classList.toggle('active', key === 'ball');
  if (moveCamera !== false) startCamTween(key);
}
btnAll.addEventListener('click', () => setRep('all'));
btnSpace.addEventListener('click', () => setRep('space'));
btnStruct.addEventListener('click', () => setRep('struct'));
btnBall.addEventListener('click', () => setRep('ball'));
document.getElementById('btnRecentre').addEventListener('click', () => startCamTween(mode));

let angleTween = null;
slider.addEventListener('input', () => { angleTween = null; applyAngle(parseFloat(slider.value)); });
document.getElementById('btnIdeal').addEventListener('click', () => {
  angleTween = { from: parseFloat(slider.value), to: 109.5, t: 0 };
});
const spinBox = document.getElementById('spin');

/* ── guided tour ─────────────────────────────────────────────────────────── */
const STEPS = [
  { title: '1 · Three pictures of one molecule', narr: 'Left: the space-filling model (true sizes). Middle: the structural drawing (measurable angles and lengths). Right: the ball-and-stick model (the bare skeleton). Every atom centre is in exactly the same place in all three.', rep: 'all', angle: 109.5 },
  { title: '2 · Solid volume', narr: 'The space-filling model shows methane as four bulky hydrogen spheres crowding a nearly hidden carbon — accurate for size, useless for reading angles.', rep: 'space', angle: 109.5 },
  { title: '3 · The measured drawing', narr: 'The drawing strips the volume away and adds numbers: the magenta arc marks the 109.5º H–C–H bond angle, the vertical arrow the 109 pm C–H bond length, and the bold wedge shows the fourth hydrogen coming toward you.', rep: 'struct', angle: 109.5 },
  { title: '4 · Distort the angle', narr: 'Push the upper hydrogen away from 109.5º and watch the readout: the four bonds stop being equivalent and the neighbouring angles compress, so the molecule is no longer tetrahedral.', rep: 'struct', angle: 140 },
  { title: '5 · Back to the tetrahedron', narr: 'Restoring 109.5º in the ball-and-stick model reveals the open skeleton: four identical bonds spread as far apart as they can get. Orbit it to see the tetrahedron from any side.', rep: 'ball', angle: 109.5 },
  { title: '6 · Compare again', narr: 'Side by side once more — same molecule, same 109 pm bonds, same 109.5º angles, three different things each picture is good at showing.', rep: 'all', angle: 109.5 }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setRep(s.rep);
  angleTween = { from: parseFloat(slider.value), to: s.angle, t: 0 };
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarr').textContent = s.narr;
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
let playTimer = null;
const btnPlay = document.getElementById('stepPlay');
btnPlay.addEventListener('click', () => {
  if (playTimer) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); return; }
  btnPlay.textContent = '❚❚ Pause'; btnPlay.classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => {
    if (stepIdx === STEPS.length - 1) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); return; }
    goToStep(stepIdx + 1);
  }, 5600);
});
goToStep(0);

/* ── per-frame updates ───────────────────────────────────────────────────── */
function tick() {
  requestAnimationFrame(tick);
  applyFades();

  if (spinBox.checked) { gSpace.rotation.y += 0.0045; gBall.rotation.y += 0.0045; }

  if (angleTween) {
    angleTween.t = Math.min(1, angleTween.t + 0.035);
    const e = angleTween.t < 0.5 ? 2 * angleTween.t * angleTween.t : 1 - Math.pow(-2 * angleTween.t + 2, 2) / 2;
    const v = angleTween.from + (angleTween.to - angleTween.from) * e;
    slider.value = v.toFixed(1);
    applyAngle(parseFloat(slider.value));
    if (angleTween.t >= 1) angleTween = null;
  }

  if (camTween) {
    camTween.t = Math.min(1, camTween.t + 0.045);
    const e = camTween.t < 0.5 ? 2 * camTween.t * camTween.t : 1 - Math.pow(-2 * camTween.t + 2, 2) / 2;
    const end = poseFor(camTween.key);
    camera.position.lerpVectors(camTween.sp, end.pos, e);
    controls.target.lerpVectors(camTween.st, end.target, e);
    camera.zoom = camTween.sz + (end.zoom - camTween.sz) * e;
    camera.updateProjectionMatrix();
    controls.update();
    if (camTween.t >= 1) camTween = null;
  } else if (poseLocked) {
    setPose(poseFor(mode));           // keeps framing correct across resizes
  }

  // labels grow gently (not linearly) when zooming into a single panel
  const zAll = poseFor('all').zoom;
  const k = Math.min(1.7, Math.max(0.6, Math.pow((camera.zoom || zAll) / zAll, 0.4)));
  _labelZoomRef = (camera.zoom || zAll) / k;
}
tick();
